/**
 * Motor de Arrastre Local Optimizado para Rutas Cíclicas
 * Soporta de forma nativa e independiente: Arrastre, Clonación y Reordenamiento masivo.
 */
(function (global, factory) {
    global.Sortable = factory();
}(this, function () { 'use strict';

    function Sortable(el, options) {
        this.el = el;
        this.options = Object.assign({ animation: 150, chosenClass: 'sortable-chosen' }, options);
        el['Sortable'] = this;

        // Forzar a que todos los elementos hijos sean físicamente arrastrables por el sistema operativo
        Array.from(el.children).forEach(child => child.setAttribute('draggable', 'true'));

        el.addEventListener('dragstart', this.onDragStart.bind(this), false);
        el.addEventListener('dragover', this.onDragOver.bind(this), false);
        el.addEventListener('dragend', this.onDragEnd.bind(this), false);
    }

    Sortable.prototype = {
        constructor: Sortable,

        onDragStart: function (evt) {
            var target = evt.target.closest('.card-cliente');
            if (!target) return;

            Sortable.active = this;
            Sortable.dragged = target;
            Sortable.parentOrigen = this.el;
            Sortable.diaOrigen = this.el.getAttribute('data-dia');

            evt.dataTransfer.effectAllowed = 'move';
            evt.dataTransfer.setData('Text', target.textContent);
            target.classList.add(this.options.chosenClass);
        },

        onDragOver: function (evt) {
            evt.preventDefault();
            evt.dataTransfer.dropEffect = 'move';

            var target = evt.target.closest('.card-cliente');
            
            if (Sortable.active && Sortable.active !== this) {
                // Permitir soltar si pertenecen al grupo unificado del tablero
                if (this.options.groupName === Sortable.active.options.groupName && this.options.permitirLlegada !== false) {
                    if (target) {
                        this.el.insertBefore(Sortable.dragged, target);
                    } else {
                        this.el.appendChild(Sortable.dragged);
                    }
                }
            } else if (Sortable.active === this) {
                // Reordenamiento posicional interno dentro de la misma columna de día
                if (target && target !== Sortable.dragged) {
                    var rect = target.getBoundingClientRect();
                    var next = (evt.clientY - rect.top) / (rect.bottom - rect.top) > 0.5;
                    this.el.insertBefore(Sortable.dragged, next ? target.nextSibling : target);
                }
            }
        },

        onDragEnd: function (evt) {
            if (!Sortable.dragged) return;

            Sortable.dragged.classList.remove(this.options.chosenClass);
            
            var listaDestino = Sortable.dragged.parentNode;
            var diaDestino = listaDestino.getAttribute('data-dia');
            var diaOrigen = Sortable.diaOrigen;

            // DETECTAR SI ES UNA ASIGNACIÓN NUEVA DESDE LA BOLSA LATERAL
            if (diaOrigen === "0" && diaDestino !== "0" && listaDestino !== Sortable.parentOrigen) {
                // Clonación visual reactiva: Dejamos una copia fija en la bolsa de disponibles
                var clonBolsa = Sortable.dragged.cloneNode(true);
                clonBolsa.setAttribute('draggable', 'true');
                Sortable.parentOrigen.appendChild(clonBolsa);
            }

            // Disparar la sincronización asíncrona hacia Laravel AJAX
            if (Sortable.active && diaDestino !== "0") {
                var event = new CustomEvent('sortable-end', {
                    bubbles: true,
                    detail: {
                        item: Sortable.dragged,
                        to: listaDestino,
                        from: Sortable.parentOrigen,
                        diaDestino: diaDestino,
                        diaOrigen: diaOrigen
                    }
                });
                this.el.dispatchEvent(event);
            }

            Sortable.active = null;
            Sortable.dragged = null;
            Sortable.parentOrigen = null;
            Sortable.diaOrigen = null;
        }
    };

    return Sortable;
}));
